export const BODY: string = "\n<p>تصویر میں پس منظر بڑھانا مختصر کام ہے جب آپ کو مراحل معلوم ہوں۔ آپ تصویر یا شفاف کٹ آؤٹ اپ لوڈ کرتے ہیں، پس منظر چنتے ہیں، فریم شکل سیٹ کرتے ہیں، اور ایکسپورٹ کرتے ہیں۔</p>\n<p>شروع کرنے سے پہلے آپ کو ایک چیز چاہیے ہوتی ہے: پیش منظر تصویر۔ یہ عام تصویر، شفاف PNG کٹ آؤٹ، لوگو، یا اسکرین شاٹ ہو سکتی ہے۔ اگر آپ کی تصویر کا پرانا پس منظر ابھی بھی ہے تو پہلے اسے ہٹائیں۔</p>\n<p>Add Background to Image ٹول کام آپ کے براؤزر میں کرتا ہے۔ کچھ بھی سرور پر اپ لوڈ نہیں ہوتا، کوئی اکاؤنٹ نہیں ہے، اور ایکسپورٹ مفت ہے۔ نیچے مراحل پر عمل کریں۔</p>\n<h2 id=\"step-1-upload-your-image\">مرحلہ 1: اپنی تصویر اپ لوڈ کریں</h2>\n<p>ٹول کھولیں اور اپنی تصویر اپ لوڈ زون پر ڈال دیں، یا اپنے آلے سے فائل چننے کے لیے کلک کریں۔ آپ تصویر کو اپنے کلپ بورڈ سے سیدھا چسپاں بھی کر سکتے ہیں۔</p>\n<p>ٹول 20 MB تک JPG، PNG، WebP، HEIC، GIF، BMP، اور SVG فائلیں قبول کرتا ہے۔ زیادہ تر تصاویر اور کٹ آؤٹ اس حد سے کہیں نیچے ہوتی ہیں۔ اگر آپ کی فائل iPhone HEIC تصویر ہے تو یہ بھی کام کرے گی۔</p>\n<p>جیسے ہی تصویر لوڈ ہوتی ہے یہ ڈیفالٹ پس منظر پر ظاہر ہوتی ہے جس کے ساتھ فریمنگ کنٹرول ہوتے ہیں۔ ایک لمحہ دیکھیں کہ پیش منظر فریم میں کیسے بیٹھتا ہے۔</p>\n<p>اگر آپ نے غلط فائل اپ لوڈ کی تو اپنی سیٹنگ کھوئے بغیر اسے بدلیں۔ ٹول آپ کو پس منظر اور فریمنگ انتخاب رکھتے ہوئے پیش منظر تصویر بدلنے دیتا ہے۔</p>\n<h2 id=\"step-2-pick-a-background-mode\">مرحلہ 2: پس منظر موڈ چنیں</h2>\n<p>تین موڈ میں سے ایک چنیں: Solid Color، Gradient، یا Blurred Photo۔ Solid Color کینوس کو واحد فلیٹ رنگ سے بھرتا ہے اور پروڈکٹ تصاویر، لوگو، اور لسٹنگ کے لیے موزوں ہے۔</p>\n<p>Gradient دو رنگوں کو زاویے پر کینوس میں ملاتا ہے۔ یہ سوشل پوسٹ، اسٹوری فریم، اور پروموشنل گرافکس کے لیے موزوں ہے، جہاں پس منظر کو توانائی بڑھانی چاہیے۔</p>\n<p>Blurred Photo کینوس کو آپ کی اپنی تصویر کی دھندلی کاپی سے بھرتا ہے۔ یہ ان تصاویر کے لیے موزوں ہے جن کی شکل فریم سے میل نہیں کھاتی، کیونکہ دھندلے کنارے خالی جگہ بھرتے ہیں۔</p>\n<p>موڈ بدلنا آپ کے پیش منظر اور فریمنگ کو رکھتا ہے، اس لیے فیصلہ کرنے سے پہلے ہر ایک آزمائیں۔ سفید پر سادہ لگنے والی پروڈکٹ گریڈینٹ پر شاندار لگ سکتی ہے، اور تصویر دھندلے پس منظر پر بہتر لگ سکتی ہے۔</p>\n<h2 id=\"step-3-choose-a-color-or-colors\">مرحلہ 3: رنگ یا رنگ چنیں</h2>\n<p>Solid Color موڈ میں فوری سوئچ سے چنیں یا درست شیڈ کے لیے کلر پکر کھولیں۔ سفید لسٹنگ کے لیے معیار ہے، برانڈ رنگ مہم کے لیے موزوں ہے۔</p>\n<p>Gradient موڈ میں دو رنگ اور زاویہ چنیں۔ ترچھا زاویہ متحرک محسوس ہوتا ہے، عمودی زاویہ پرسکون محسوس ہوتا ہے، اور افقی زاویہ چوڑا محسوس ہوتا ہے۔ قریب رنگوں سے شروع کریں۔</p>\n<p>Blurred Photo موڈ میں چننے کے لیے کوئی رنگ نہیں ہے، کیونکہ پس منظر تصویر سے ہی آتا ہے۔ اس کے بجائے دھندلا پن رداس سیٹ کریں۔ ہلکا دھندلا پن شکلیں رکھتا ہے۔</p>\n<p>آگے بڑھنے سے پہلے رنگ کو پیش منظر کے خلاف چیک کریں۔ تاریک پس منظر پر تاریک پروڈکٹ غائب ہو جاتا ہے، اور ہلکے پس منظر پر ہلکا لوگو دھل جاتا ہے۔ کنٹراسٹ اہمیت رکھتا ہے۔</p>\n<h2 id=\"step-4-set-the-canvas-ratio\">مرحلہ 4: کینوس تناسب سیٹ کریں</h2>\n<p>کینوس شکل اس جگہ کے لیے چنیں جہاں تصویر شائع ہو گی۔ مربع فیڈ، لسٹنگ، اور تھمب نیل کے لیے موزوں ہے۔ 16:9 وائڈ اسکرین شکل بینر اور ویڈیو تھمب نیل کے لیے موزوں ہے۔</p>\n<p>آؤٹ پٹ ابعاد تناسب اور آپ کے ماخذ تصویر کے سائز سے آتے ہیں۔ بڑا ماخذ بڑا ایکسپورٹ دیتا ہے، جبکہ چھوٹا ماخذ چھوٹا دیتا ہے۔</p>\n<p>سوچیں کہ پلیٹفارم تصویر کو کہاں کراپ کرے گا۔ سوشل ایپس پیش نظاروں کو اپنی شکلوں پر کراپ کرتی ہیں، اور کنارے کے قریب پیش منظر کٹ سکتا ہے۔ اسے بیچ میں رکھیں۔</p>\n<p>اگر آپ کو یقین نہیں کہ تصویر کہاں استعمال ہو گی تو مربع چنیں۔ یہ سب سے معاف کرنے والی شکل ہے، یہ ہر جگہ پیش گوئی سے کراپ ہوتی ہے، اور یہ تھمب نیل، فیڈ پوسٹ، اور لسٹنگ کے طور پر کام کرتی ہے۔</p>\n<h2 id=\"step-5-scale-the-foreground\">مرحلہ 5: پیش منظر کو سکیل کریں</h2>\n<p>Image Scale کنٹرول استعمال کریں تاکہ سیٹ کریں کہ پیش منظر فریم میں کتنا بڑا ظاہر ہو۔ بڑا پیمانہ کینوس بھرتا ہے اور موضوع کو ہیرو بناتا ہے۔ چھوٹا پیمانہ سانس لینے کی جگہ چھوڑتا ہے۔</p>\n<p>موضوع کے گرد سانس لینے کی جگہ چھوڑیں۔ فریم کے کنارے سے دبا ہوا پروڈکٹ تنگ لگتا ہے، جبکہ بڑے خالی کینوس میں تیرتا ہوا کھویا ہوا لگتا ہے۔</p>\n<p>جب کینوس شکل تصویر شکل سے مختلف ہو تو پیمانہ فریمنگ کام کرتا ہے۔ مربع کینوس پر لمبی تصویر کو فٹ ہونے کے لیے چھوٹے پیمانے کی ضرورت ہوتی ہے، اور دھندلا پس منظر خالی جگہ بھرتا ہے۔</p>\n<p>نتیجہ کا پیش نظارہ اس سائز پر کریں جس پر یہ دیکھا جائے گا۔ تھمب نیل تصویر کو ایڈیٹر سے کہیں چھوٹا دکھاتا ہے، اس لیے ایڈیٹر میں فراخ لگنے والے مارجن تھمب نیل میں تنگ لگ سکتے ہیں۔</p>\n<h2 id=\"step-6-add-roundness-and-shadow\">مرحلہ 6: گولائی اور سایہ بڑھائیں</h2>\n<p>گولائی مستطیل پیش منظر تصویر کے کونوں کو نرم کرتی ہے۔ ہلکی گولائی کارڈ جیسا احساس دیتی ہے جو سوشل پوسٹ اور ایپ اسکرین شاٹ کے لیے موزوں ہے۔ مضبوط گولائی دائرہ بناتی ہے۔</p>\n<p>شفاف PNG کٹ آؤٹ کے لیے گولائی کا کم اثر ہوتا ہے، کیونکہ کونے پہلے سے آرٹ ورک سے طے شدہ ہیں۔ کنٹرول مستطیل تصاویر کے لیے سب سے زیادہ اہمیت رکھتا ہے۔</p>\n<p>ڈراپ شیڈو پیش منظر کو پس منظر سے اٹھاتا ہے اور گہرائی بڑھاتا ہے۔ یہ شفاف کٹ آؤٹ اور لوگو کے ساتھ بہترین کام کرتا ہے، جہاں سایہ موضوع کی شکل کی پیروی کرتا ہے۔</p>\n<p>دونوں اثرات کو معمولی رکھیں۔ بھاری سایہ یا انتہائی رداس تصویر کے بجائے علاج کی طرف توجہ کھینچتا ہے۔ اتنی گہرائی اور پالش بڑھائیں کہ تصویر تیار لگے۔</p>\n<h2 id=\"step-7-check-the-preview\">مرحلہ 7: پیش نظارہ چیک کریں</h2>\n<p>ایکسپورٹ سے پہلے مکمل پیش نظارہ دیکھیں۔ چیک کریں کہ پیش منظر بیچ میں ہے، مارجن برابر ہیں، اور پس منظر رنگ یا گریڈینٹ ویسا لگتا ہے جیسا آپ چاہتے تھے۔</p>\n<p>پیش منظر کے کنارے چیک کریں۔ کھردرے کنارے والا کٹ آؤٹ یا پرانے پس منظر سے بچا ہوا ہالہ ٹھوس رنگ کے خلاف صاف ظاہر ہوتا ہے۔ اگر کنارہ خراب لگے تو کٹ آؤٹ پہلے صاف کریں۔</p>\n<p>اگر ہو سکے تو تصویر کو اپنے فون پر دیکھیں۔ ڈیسک ٹاپ مانیٹر پر معمولی لگنے والا پس منظر فون اسکرین پر بلند لگ سکتا ہے، اور ہموار لگنے والا گریڈینٹ بینڈ دکھا سکتا ہے۔</p>\n<p>اگر آپ غیر یقینی ہوں تو تینوں پس منظر موڈ کا ایک آخری بار موازنہ کریں۔ بدلنا مفت ہے اور آپ کی فریمنگ رکھتا ہے، اس لیے حتمی موازنہ سیکنڈوں میں ہوتا ہے اور اکثر فیصلہ بدل دیتا ہے۔</p>\n<h2 id=\"step-8-export-and-download\">مرحلہ 8: ایکسپورٹ اور ڈاؤن لوڈ کریں</h2>\n<p>ایکسپورٹ فارمیٹ چنیں۔ JPG تصاویر اور کسی بھی تصویر کے لیے موزوں ہے جہاں چھوٹی فائل اہمیت رکھتی ہے، جیسے سوشل پوسٹ یا ویب سائٹ بینر۔ PNG تیز متن والی تصاویر کے لیے موزوں ہے۔</p>\n<p>ڈاؤن لوڈ پر کلک کریں اور تیار تصویر آپ کے آلے پر محفوظ ہو جاتی ہے۔ فائل نام پس منظر سیٹنگ کو ظاہر کرتا ہے، اس لیے آپ مختلف ورژن کو الگ بتا سکتے ہیں جب آپ کئی ایکسپورٹ کریں۔</p>\n<p>ڈاؤن لوڈ شدہ فائل کھولیں اور اسے ایک بار اور دیکھیں۔ سائز، فارمیٹ، اور ظاہری شکل کو اس سائز پر چیک کریں جس پر یہ شائع ہو گی۔ اب فوری چیک بعد میں شرمندگی بچاتا ہے۔</p>\n<p>اگر نتیجہ درست نہ ہو تو ایک سیٹنگ بدلیں اور دوبارہ ایکسپورٹ کریں۔ ٹول آپ کے بنائے گئے ورژن کی تعداد محدود نہیں کرتا، اس لیے آزادانہ تکرار کریں۔ مختلف رنگ والی دوسری ایکسپورٹ سیکنڈوں میں ہوتی ہے۔</p>\n<h2 id=\"step-9-use-the-image\">مرحلہ 9: تصویر استعمال کریں</h2>\n<p>تیار تصویر کو اس کی منزل پر اپ لوڈ کریں: دکان لسٹنگ، سوشل پوسٹ، سلائیڈ ڈیک، یا ویب سائٹ بینر۔ فائل کو ویسے استعمال کریں، کیونکہ پس منظر، فریمنگ، اور فارمیٹ پہلے سے سیٹ ہیں۔</p>\n<p>دکان لسٹنگ کے لیے تصویر کو اس سے میل کھانے والے پروڈکٹ عنوان اور تفصیل کے ساتھ جوڑیں۔ صاف پس منظر والی تصویر اور واضح عنوان مصروف تصویر سے بہتر بدلتی ہے۔</p>\n<p>سوشل میڈیا کے لیے تصویر کو اس تناسب میں پوسٹ کریں جو پلیٹفارم پسند کرے اور کیپشن الگ بڑھائیں۔ تصویر بصری پیغام لے کر آتی ہے، اور کیپشن الفاظ لے کر آتا ہے۔</p>\n<p>ایکسپورٹ شدہ فائل کو اس منزل کے لیے اپنے ماسٹر کاپی کے طور پر رکھیں۔ اگر آپ کو بعد میں مختلف تناسب چاہیے تو اصل پیش منظر کے ساتھ ٹول پر واپس آئیں اور دوبارہ ایکسپورٹ کریں۔</p>\n<h2 id=\"backgrounds-for-different-photo-types\">مختلف تصویر اقسام کے لیے پس منظر</h2>\n<p>پورٹریٹ کو ایسا پس منظر چاہیے ہوتا ہے جو چہرے کو مرکز رکھے۔ نرم ٹھوس رنگ یا نرم دھندلا پس منظر اچھی طرح کام کرتا ہے، کیونکہ دونوں شخص کے پیچھے خاموش بیٹھتے ہیں۔</p>\n<p>پروڈکٹ شاٹ کو الٹا علاج چاہیے ہوتا ہے: پس منظر جتنا ممکن ہو غیر جانبدار ہونا چاہیے تاکہ خریدار پروڈکٹ کو پرکھیں، منظر کو نہیں۔ سفید معیار ہے، اور برانڈ رنگ مستقل مزاجی کے لیے کام کرتا ہے۔</p>\n<p>کھانے کی فوٹوگرافی گرم، قدرتی پس منظر سے فائدہ اٹھاتی ہے۔ نرم کریم، ہلکا لکڑی لہجہ، یا دھندلا باورچی خانہ منظر کھانے کو لذیذ بناتا ہے۔ ٹھنڈا نیلا کھانے کو غیر لذیذ بناتا ہے۔</p>\n<p>اسکرین شاٹ اور ایپ موک اپ ٹھوس برانڈ رنگ یا معمولی گریڈینٹ پر بہترین لگتے ہیں۔ صاف پس منظر انٹرفیس کو پریزنٹیشن سلائیڈ کی طرح فریم کرتا ہے، اور اسکرین شاٹ پیشہ ورانہ لگتا ہے۔</p>\n<p>لوگو اور بیج کو ایسا پس منظر چاہیے ہوتا ہے جو اس سے میل کھائے جہاں وہ ظاہر ہوں گے۔ ویب سائٹ ہیڈر کے لیے مقرر لوگو کو شفافیت یا ہیڈر سے میل کھانے والا بھرنا چاہیے ہوتا ہے۔</p>\n<p>پالتو اور جنگلی حیات تصاویر دھندلے تصویر پس منظر کے لیے موزوں ہیں، کیونکہ دھندلے رنگ اصل ماحول تجویز کرتے ہیں جبکہ جانور تیز رہتا ہے۔ ان کے پیچھے ٹھوس رنگ مصنوعی لگتا ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: پس منظر چیک لسٹ</h2>\n<p>پیش منظر اپ لوڈ کریں، Solid، Gradient، یا Blurred Photo چنیں، رنگ یا دھندلا پن چنیں، منزل کے لیے کینوس تناسب سیٹ کریں، سانس لینے کی جگہ کے ساتھ پیش منظر کو سکیل کریں۔</p>\n<p>تصاویر کے لیے JPG اور تیز متن کے لیے PNG ایکسپورٹ کریں، پھر ڈاؤن لوڈ کو اس سائز پر چیک کریں جس پر یہ دیکھا جائے گا۔ اگر کٹ آؤٹ کا کنارہ کھردرا لگے تو پہلے کٹ آؤٹ صاف کریں۔</p>\n<p>ہر موڈ کی مکمل گائیڈ کے لیے <a href=\"/ur/blog/tasveer-par-background-rehnumai/\">Add Background to Images: Complete Guide</a> پڑھیں، اور پروڈکٹ مخصوص مشورے کے لیے <a href=\"/ur/blog/product-photo-backgrounds/\">Product Photo Backgrounds: Colours and Context</a> پڑھیں۔</p>\n";

